// qp_dump: records every WBIC quadratic program of the parity sweep (the same
// 128 states x 3 commands as parity_dump, generated by tools/sweep.hh), exactly
// as QuadProg++ receives it, together with QuadProg++'s answer.
//
// usage: qp_dump <urdf> <out.qp> [n_states=128] [seed=12345]
//
// QP convention: minimize 1/2 x'Gx + g0'x  s.t.  CE'x + ce0 = 0,  CI'x + ci0 >= 0.
//
// File layout (little endian):
//   header, 8 x uint32: magic 'QPDS' (0x53445051), version 1, n_records,
//                       n_states, n_cmds (3), seed, 0, 0
//   n_records x record, in sweep order (tick = state * 3 + cmd):
//     uint32 tick, n, p, m                      sizes (n vars, p equalities, m inequalities)
//     double G[n*n]                             row-major, as handed to the solver
//     double g0[n]
//     double CE[n*p]                            row-major n x p (one constraint per column)
//     double ce0[p]
//     double CI[n*m]                            row-major n x m (one constraint per column)
//     double ci0[m]
//     double x[n]                               QuadProg++ solution
//     double f                                  QuadProg++ objective value (its return value)
//   Records are variable-length (n = 6 + 3*contacts, p = 6, m = 6*contacts, or
//   m = 1 with a zero column when there are no contacts).
// The data are the double values QuadProg++ gets (WBIC<float> builds them from
// float quantities). G is recorded before the solver factorises it in place.
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "controllers/wbc/WBIC/QpRecorder.hpp"
#include "sweep.hh"

namespace {
struct Dump : WbicQpRecorder {
  std::vector<double> cur;  // problem of the tick in flight (sizes in header vars)
  uint32_t n = 0, p = 0, m = 0;
  bool have = false;
  std::vector<unsigned char> bytes;  // whole record stream
  uint32_t nrec = 0;
  int maxN = 0, maxP = 0, maxM = 0;

  void problem(int n_, int p_, int m_, const double* G, const double* g0, const double* CE,
               const double* ce0, const double* CI, const double* ci0) override {
    n = n_; p = p_; m = m_;
    cur.clear();
    auto add = [&](const double* a, size_t len) { cur.insert(cur.end(), a, a + len); };
    add(G, (size_t)n * n); add(g0, n); add(CE, (size_t)n * p); add(ce0, p);
    add(CI, (size_t)n * m); add(ci0, m);
    have = true;
  }
  void solution(double f, const double* x, int n_) override {
    if (!have) return;
    add_record(f, x, n_);
    have = false;
  }
  void put(const void* d, size_t len) {
    const unsigned char* b = static_cast<const unsigned char*>(d);
    bytes.insert(bytes.end(), b, b + len);
  }
  uint32_t tick = 0;
  void add_record(double f, const double* x, int n_) {
    const uint32_t head[4] = {tick, n, p, m};
    put(head, sizeof head);
    put(cur.data(), cur.size() * sizeof(double));
    put(x, (size_t)n_ * sizeof(double));
    put(&f, sizeof f);
    ++nrec;
    if ((int)n > maxN) maxN = n;
    if ((int)p > maxP) maxP = p;
    if ((int)m > maxM) maxM = m;
  }
};
}  // namespace

int main(int argc, char** argv) {
  if (argc < 3) {
    std::fprintf(stderr, "usage: %s <urdf> <out.qp> [n_states=128] [seed=12345]\n", argv[0]);
    return 2;
  }
  const std::string urdf = argv[1], outpath = argv[2];
  const uint32_t n_states = argc > 3 ? std::atoi(argv[3]) : 128;
  const uint32_t seed = argc > 4 ? std::atoi(argv[4]) : 12345;

  Dump dump;
  wbicQpRecorder() = &dump;
  uint32_t failed = 0, ticks = 0;
  auto onTick = [&](const wbch::TickInput& in, uint32_t rec) {
    dump.tick = rec;
    dump.have = false;
    wbch::Harness h;
    wbch::TickOutput out;
    std::memset(&out, 0, sizeof out);
    bool ok = h.init(urdf);
    if (ok) {
      try { h.tick(in, out); } catch (...) { ok = false; }
    }
    if (!ok || dump.have) ++failed;  // dump.have: problem seen but no solution (solver threw)
    ++ticks;
  };
  if (!sweep::forEachTick(urdf, n_states, seed, onTick)) return 1;
  wbicQpRecorder() = nullptr;

  FILE* f = std::fopen(outpath.c_str(), "wb");
  if (!f) { std::perror("open out"); return 1; }
  const uint32_t hdr[8] = {0x53445051u, 1u, dump.nrec, n_states, 3u, seed, 0u, 0u};
  std::fwrite(hdr, sizeof hdr, 1, f);
  std::fwrite(dump.bytes.data(), 1, dump.bytes.size(), f);
  std::fclose(f);
  std::printf("qp_dump: %u ticks, %u QPs recorded, %u failed ticks, max n=%d p=%d m=%d, %zu bytes -> %s\n",
              ticks, dump.nrec, failed, dump.maxN, dump.maxP, dump.maxM,
              sizeof hdr + dump.bytes.size(), outpath.c_str());
  return failed ? 1 : 0;
}
